   147	            if (byte_index + length_of_length >= bytes_max) {
   148	                /* This is an error */
   149	                byte_index = ptls_asn1_error_message("Incorrect length coding", bytes_max, byte_index, level, log_ctx);
   150	                *decode_error = PTLS_ERROR_BER_MALFORMED_LENGTH;
