   154	                    *length |= bytes[byte_index++];
   155	                }
   156	
   157	                if (length_of_length == 0) {
   158	                    *last_byte = bytes_max;
   159	                    *indefinite_length = 1;
   160	                } else {
   161	                    *last_byte = byte_index + *length;
   162	                }
   163	            }
   164	        } else {
